/* @lc app=leetcode id=3738 lang=kotlin */ class Solution { fun longestSubarray(nums: IntArray): Int = nums.size.let { n -> nums.indices.runningFold(0) { l, i -> if (i > 0 && nums[i] >= nums[i - 1]) l + 1 else 1 }.drop(1).let { left -> (n - 1 downTo 0).runningFold(0) { r, i -> if (i < n - 1 && nums[i] <= nums[i + 1]) r + 1 else 1 }.drop(1).reversed().let { right -> nums.indices.maxOf { i -> if (i == 0) (if (n > 1) right[1] + 1 else 1) else if (i == n - 1) left[n - 2] + 1 else if (nums[i - 1] <= nums[i + 1]) left[i - 1] + 1 + right[i + 1] else maxOf(left[i - 1], right[i + 1]) + 1 } } } } }